mapper.select:
SELECT a.user_ques_id , a.ans_status , a.created_at , a.couple_id , b.ques_id , a.couple_ques_no , b.ques_content FROM tb_user_random_question a JOIN tb_random_question b ON a.ques_id = b.ques_id WHERE a.couple_id = #{coupleId}
AND a.user_ques_id < #{lastId}
AND b.ques_content LIKE CONCAT('%', #{keyword}, '%')
ORDER BY a.user_ques_id DESC LIMIT #{size}

SELECT user_ques_id
     , ans_status
     , created_at
     , couple_id
  FROM tb_user_random_question
 WHERE couple_id = (
SELECT couple_id
  FROM TB_COUPLE_LIST
 WHERE member_id1 = #{memberId}
    OR member_id2 = #{memberId}
)
   AND user_ques_id = #{userQuesIdx}

SELECT ans_status
FROM tb_user_random_question
WHERE user_ques_id = #{userQuesId}

SELECT EXISTS (
    SELECT 1 FROM tb_user_random_question a
    WHERE a.couple_id = #{coupleId}
    AND a.couple_ques_no = #{coupleQuesNo}
    AND a.ans_status = #{ansStatus}
    LIMIT 1
)
